custom_css:
/* ==========================================================================
   Personnalisation CSS — Kaïro Console Launcher
   Toutes ces classes sont surchargeables directement depuis ce fichier !
   ========================================================================== */

/* Carte active mise en valeur dans le carrousel avec halo néon */
.kairo-carousel-card-focused {
  border-color: #f43f5e !important;
  box-shadow: 0 0 25px rgba(244, 63, 94, 0.5), 0 0 50px rgba(244, 63, 94, 0.2) !important;
}

/* Bouton principal Jouer */
.kairo-hero-btn-play {
  box-shadow: 0 8px 20px -4px rgba(244, 63, 94, 0.5) !important;
}

/* Barre d'aide manette en bas */
.kairo-controller-bar {
  letter-spacing: 0.5px;
}
